INSERT INTO products (id,name,tagline,description,collections,category,price,mrp,hsn,fabric,gsm,fit,care,origin,model_info,size_group,images,colours,cost_fabric,cost_labour,cost_transport,cost_duties,is_new,status,sort,created_at) VALUES ('linen-shirt','Everyday Linen Shirt','Washed European flax, cut for warm days.','The shirt we wear most. Stone-washed 100% European flax linen that is soft from the first wear, with a relaxed collar, mother-of-pearl effect buttons and a slightly longer back hem so it sits well tucked or loose.','["Men","New"]','Shirts',249900,299900,'6205','100% European flax linen, stone washed','150 GSM','Relaxed regular fit. Take your usual size; size down for a closer fit.','Machine wash cold, gentle cycle. Line dry in shade. Warm iron while damp. Do not tumble dry.','Woven in Belgium and Lithuania, cut and stitched in Tiruppur, Tamil Nadu.','Rohan is 6''0" (183 cm) and wears size M. Chest 98 cm, waist 82 cm.','tops','["/img/products/linen-shirt-1.jpg","/img/products/linen-shirt-2.jpg"]','[{"name":"Sand","hex":"#D9CBB0","image":"/img/products/linen-shirt-1.jpg"},{"name":"Sage","hex":"#9AA58B","image":"/img/products/linen-shirt-sage.jpg"},{"name":"White","hex":"#F4F1EA","image":"/img/products/linen-shirt-white.jpg"}]',84966,49980,12495,17493,1,'active',1,'2026-11-01T00:00:00.000Z');
INSERT INTO products (id,name,tagline,description,collections,category,price,mrp,hsn,fabric,gsm,fit,care,origin,model_info,size_group,images,colours,cost_fabric,cost_labour,cost_transport,cost_duties,is_new,status,sort,created_at) VALUES ('organic-tee','Heavyweight Organic Tee','240 GSM GOTS-certified cotton. Holds its shape.','A proper everyday tee: dense 240 GSM single-jersey from GOTS-certified organic cotton, a ribbed crew neck that does not stretch out, and a boxy but not oversized body. Pre-shrunk and garment-dyed.','["Women","Men","Basics"]','T-shirts',129900,149900,'6109','100% GOTS-certified organic cotton single jersey','240 GSM','Boxy regular fit with a dropped shoulder. True to size.','Machine wash cold inside out. Tumble dry low or line dry. Do not bleach.','Grown in Maharashtra, knitted and sewn in Tiruppur, Tamil Nadu.','Anika is 5''7" (170 cm), 84-66-90 cm, and wears size S. Wears size S for a fitted look, M for relaxed.','tops','["/img/products/organic-tee-1.jpg","/img/products/organic-tee-2.jpg"]','[{"name":"Off-white","hex":"#F1ECE1","image":"/img/products/organic-tee-1.jpg"},{"name":"Black","hex":"#1B1A17","image":"/img/products/organic-tee-black.jpg"},{"name":"Clay","hex":"#B8876B","image":"/img/products/organic-tee-clay.jpg"}]',42867,24681,6495,7794,0,'active',2,'2026-11-01T00:00:00.000Z');
INSERT INTO products (id,name,tagline,description,collections,category,price,mrp,hsn,fabric,gsm,fit,care,origin,model_info,size_group,images,colours,cost_fabric,cost_labour,cost_transport,cost_duties,is_new,status,sort,created_at) VALUES ('pique-polo','Piqué Knit Polo','Textured organic piqué, a quieter kind of polo.','A two-button polo in breathable organic cotton piqué with a soft knit collar that stays flat. Wear it with the pleated chino for work or with shorts on a weekend.','["Men","Basics"]','Polos',179900,209900,'6105','100% organic cotton piqué','210 GSM','Regular fit, slightly tapered through the waist.','Machine wash cold. Dry flat or tumble dry low. Cool iron.','Knitted and made in Tiruppur, Tamil Nadu.','Rohan is 6''0" (183 cm) and wears size M. Chest 98 cm.','tops','["/img/products/pique-polo-1.jpg","/img/products/pique-polo-2.jpg"]','[{"name":"Forest","hex":"#34483A","image":"/img/products/pique-polo-1.jpg"}]',57568,35980,8995,12593,0,'active',3,'2026-11-01T00:00:00.000Z');
INSERT INTO products (id,name,tagline,description,collections,category,price,mrp,hsn,fabric,gsm,fit,care,origin,model_info,size_group,images,colours,cost_fabric,cost_labour,cost_transport,cost_duties,is_new,status,sort,created_at) VALUES ('pleated-chino','Relaxed Pleated Chino','Single pleat, easy leg, stone-washed twill.','A relaxed pleated chino in a soft stone-washed cotton twill. High enough rise to sit comfortably, a single forward pleat for room and a gently tapered leg that does not bunch at the shoe.','["Men"]','Trousers',279900,329900,'6203','98% cotton, 2% elastane twill','260 GSM','Relaxed through the thigh, tapered below the knee. True to size.','Machine wash cold. Tumble dry low. Warm iron if needed.','Woven in Gujarat, stitched in Bengaluru, Karnataka.','Rohan is 6''0" (183 cm) and wears size M. Waist 82 cm, wears size M (32).','bottoms','["/img/products/pleated-chino-1.jpg","/img/products/pleated-chino-2.jpg"]','[{"name":"Stone","hex":"#C8BBA3","image":"/img/products/pleated-chino-1.jpg"}]',83970,61578,13995,19593,0,'active',4,'2026-11-01T00:00:00.000Z');
INSERT INTO products (id,name,tagline,description,collections,category,price,mrp,hsn,fabric,gsm,fit,care,origin,model_info,size_group,images,colours,cost_fabric,cost_labour,cost_transport,cost_duties,is_new,status,sort,created_at) VALUES ('linen-trouser','Drawstring Linen Trouser','Wide leg, soft waist, nothing to fuss over.','A wide-leg trouser with an elasticated, drawstring waist and deep side pockets. Midweight washed linen that drapes instead of clinging, and softens with every wash.','["Women","New"]','Trousers',229900,269900,'6204','100% washed linen','170 GSM','Relaxed, high waist, wide leg. Full length 98 cm on size M.','Machine wash cold, gentle. Line dry. Iron warm while damp.','Linen from Belgium, made in Kochi, Kerala.','Anika is 5''7" (170 cm), 84-66-90 cm, and wears size S. Waist 66 cm, wears size S.','bottoms','["/img/products/linen-trouser-1.jpg","/img/products/linen-trouser-2.jpg"]','[{"name":"Sage","hex":"#9AA58B","image":"/img/products/linen-trouser-1.jpg"}]',78166,48279,11495,16093,1,'active',5,'2026-11-01T00:00:00.000Z');
INSERT INTO products (id,name,tagline,description,collections,category,price,mrp,hsn,fabric,gsm,fit,care,origin,model_info,size_group,images,colours,cost_fabric,cost_labour,cost_transport,cost_duties,is_new,status,sort,created_at) VALUES ('wrap-midi-dress','Cotton Wrap Midi Dress','A tie-waist wrap in soft handloom-feel cotton.','An easy wrap dress in breathable cotton poplin with a self-tie waist, flutter-free sleeves and a calf-skimming hem. Adjustable at the waist, so it fits across the day.','["Women","New"]','Dresses',319900,379900,'6204','100% cotton poplin, garment dyed','130 GSM','Wrap closure, true to size, adjustable waist. Length 118 cm on size M.','Machine wash cold. Line dry. Warm iron on reverse.','Cut and sewn in Jaipur, Rajasthan using Indian cotton.','Anika is 5''7" (170 cm), 84-66-90 cm, and wears size S. Wears size S.','dress','["/img/products/wrap-midi-dress-1.jpg","/img/products/wrap-midi-dress-2.jpg"]','[{"name":"Clay","hex":"#B8876B","image":"/img/products/wrap-midi-dress-1.jpg"}]',105567,73577,15995,19194,1,'active',6,'2026-11-01T00:00:00.000Z');
INSERT INTO products (id,name,tagline,description,collections,category,price,mrp,hsn,fabric,gsm,fit,care,origin,model_info,size_group,images,colours,cost_fabric,cost_labour,cost_transport,cost_duties,is_new,status,sort,created_at) VALUES ('kurta-shirt','Mandarin Kurta Shirt','A short kurta, cut like a shirt. No embroidery.','A short kurta in lightweight cotton with a mandarin collar, concealed placket and side vents. Works over jeans, chinos or with a pyjama at home. Plain, with no embroidery or print.','["Men","New"]','Shirts',199900,239900,'6205','100% cotton, mill-washed','140 GSM','Regular fit, hip length with side vents. True to size.','Machine wash cold. Line dry. Medium iron.','Handloom-feel cotton from Salem, made in Erode, Tamil Nadu.','Rohan is 6''0" (183 cm) and wears size M. Wears size M.','tops','["/img/products/kurta-shirt-1.jpg","/img/products/kurta-shirt-2.jpg"]','[{"name":"Off-white","hex":"#F1ECE1","image":"/img/products/kurta-shirt-1.jpg"}]',61969,45977,9995,11994,1,'active',7,'2026-11-01T00:00:00.000Z');
INSERT INTO products (id,name,tagline,description,collections,category,price,mrp,hsn,fabric,gsm,fit,care,origin,model_info,size_group,images,colours,cost_fabric,cost_labour,cost_transport,cost_duties,is_new,status,sort,created_at) VALUES ('overshirt','Brushed Cotton Overshirt','A light layer with a soft, brushed hand.','An overshirt in brushed cotton twill with a chest pocket and a stitched-in-place collar. Heavy enough to wear as a light jacket, soft enough to sleep in. Button it up or wear it open.','["Men","New"]','Outerwear',349900,419900,'6201','100% brushed organic cotton twill','280 GSM','Relaxed, layer-friendly. Take your usual size.','Machine wash cold, gentle. Dry flat. Cool iron.','Woven in Erode, finished and stitched in Tiruppur, Tamil Nadu.','Rohan is 6''0" (183 cm) and wears size M. Wears size M.','tops','["/img/products/overshirt-1.jpg","/img/products/overshirt-2.jpg"]','[{"name":"Olive","hex":"#4F5638","image":"/img/products/overshirt-1.jpg"}]',115467,76978,17495,24493,1,'active',8,'2026-11-01T00:00:00.000Z');
INSERT INTO products (id,name,tagline,description,collections,category,price,mrp,hsn,fabric,gsm,fit,care,origin,model_info,size_group,images,colours,cost_fabric,cost_labour,cost_transport,cost_duties,is_new,status,sort,created_at) VALUES ('oversized-hoodie','Oversized French Terry Hoodie','Loopback terry, 340 GSM, made to be lived in.','A heavyweight hoodie in loopback french terry with a double-layered hood, a kangaroo pocket and a roomy, dropped-shoulder cut. Brushed on the inside for warmth without bulk.','["Women","Basics"]','Hoodies',299900,349900,'6110','100% organic cotton french terry','340 GSM','Oversized. Size down for a regular fit.','Machine wash cold inside out. Dry flat or tumble dry low.','Knitted and sewn in Tiruppur, Tamil Nadu.','Anika is 5''7" (170 cm), 84-66-90 cm, and wears size S. Wears size S for an oversized look.','tops','["/img/products/oversized-hoodie-1.jpg","/img/products/oversized-hoodie-2.jpg"]','[{"name":"Warm grey","hex":"#B5ADA2","image":"/img/products/oversized-hoodie-1.jpg"}]',104965,59980,14995,17994,0,'active',9,'2026-11-01T00:00:00.000Z');
INSERT INTO products (id,name,tagline,description,collections,category,price,mrp,hsn,fabric,gsm,fit,care,origin,model_info,size_group,images,colours,cost_fabric,cost_labour,cost_transport,cost_duties,is_new,status,sort,created_at) VALUES ('linen-shorts','Linen Blend Shorts','Mid-thigh, elastic back waist, built for summer.','Easy shorts in a linen-cotton blend with a flat front, elasticated back waist and two deep pockets. A 7-inch inseam that sits at mid-thigh.','["Men","Basics"]','Shorts',149900,179900,'6203','55% linen, 45% organic cotton','160 GSM','Regular fit with a 7 in inseam. True to size.','Machine wash cold. Line dry. Iron warm.','Made in Kochi, Kerala.','Rohan is 6''0" (183 cm) and wears size M. Waist 82 cm, wears size M.','bottoms','["/img/products/linen-shorts-1.jpg","/img/products/linen-shorts-2.jpg"]','[{"name":"Navy","hex":"#26324A","image":"/img/products/linen-shorts-1.jpg"}]',44970,29980,7495,10493,0,'active',10,'2026-11-01T00:00:00.000Z');
INSERT INTO products (id,name,tagline,description,collections,category,price,mrp,hsn,fabric,gsm,fit,care,origin,model_info,size_group,images,colours,cost_fabric,cost_labour,cost_transport,cost_duties,is_new,status,sort,created_at) VALUES ('ribbed-tank','Ribbed Cotton Tank','A 2x2 rib that stays close and stays put.','A close-fitting tank in a stretchy 2x2 organic cotton rib with a scooped neck. Made to layer under the linen shirt or wear alone.','["Women","Basics"]','Tops',89900,109900,'6109','95% organic cotton, 5% elastane rib','200 GSM','Close fit, cropped at the waist. Size up for a looser fit.','Machine wash cold. Line dry. Do not iron the rib.','Knitted and sewn in Tiruppur, Tamil Nadu.','Anika is 5''7" (170 cm), 84-66-90 cm, and wears size S. Wears size S.','tops','["/img/products/ribbed-tank-1.jpg","/img/products/ribbed-tank-2.jpg"]','[{"name":"Off-white","hex":"#F1ECE1","image":"/img/products/ribbed-tank-1.jpg"}]',26970,17980,4495,5394,0,'active',11,'2026-11-01T00:00:00.000Z');
INSERT INTO products (id,name,tagline,description,collections,category,price,mrp,hsn,fabric,gsm,fit,care,origin,model_info,size_group,images,colours,cost_fabric,cost_labour,cost_transport,cost_duties,is_new,status,sort,created_at) VALUES ('canvas-tote','Everyday Canvas Tote','Heavy 12 oz canvas that carries a laptop and lunch.','A roomy tote in heavy natural cotton canvas with reinforced, double-stitched handles and an inner pocket. Plain and unprinted, so it goes with everything.','["Basics","Women","Men"]','Accessories',99900,119900,'4202','100% cotton canvas, 12 oz','400 GSM','One size: 38 cm wide, 40 cm tall, 12 cm deep. Handle drop 26 cm.','Spot clean. Hand wash cold if needed. Dry flat.','Stitched by a cooperative in Kozhikode, Kerala.','Holds up to 8 kg.','onesize','["/img/products/canvas-tote-1.jpg","/img/products/canvas-tote-2.jpg"]','[{"name":"Natural","hex":"#E3D8C0","image":"/img/products/canvas-tote-1.jpg"}]',31968,21978,5994,5994,0,'active',12,'2026-11-01T00:00:00.000Z');
